package com.company.skillplatform.git.application;

import com.company.skillplatform.agentworkflow.application.WorkflowRuntimeEventService;
import com.company.skillplatform.agentworkflow.application.WorkflowSseService;
import com.company.skillplatform.common.application.BusinessException;
import com.company.skillplatform.git.domain.GitRemotePort;
import com.company.skillplatform.git.infrastructure.GitProperties;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class GitStageWatchService {
    private final JdbcTemplate jdbc; private final GitRemotePort remote; private final GitProperties properties; private final WorkflowRuntimeEventService events; private final WorkflowSseService sse;
    public GitStageWatchService(JdbcTemplate jdbc,GitRemotePort remote,GitProperties properties,WorkflowRuntimeEventService events,WorkflowSseService sse){this.jdbc=jdbc;this.remote=remote;this.properties=properties;this.events=events;this.sse=sse;}
    @Transactional public void startStage(Long runId,Long stageRunId,String stageKey){List<Long> snapshots=jdbc.query("select r.id from workflow_run_git_repository r join workflow_run_git_repository_stage s on s.workflow_run_git_repository_id=r.id where r.workflow_run_id=? and r.status='ACTIVE' and s.stage_key=?",(rs,n)->rs.getLong(1),runId,stageKey);for(Long snapshot:snapshots)createWatch(runId,stageRunId,snapshot);}
    @Transactional public void attachSnapshotToActiveStages(Long runId,Long snapshotId){Map<String,Object> repository=jdbc.queryForMap("select display_name,tracked_branch from workflow_run_git_repository where id=?",snapshotId);publish(runId,null,"repository.added",Map.of("repositoryId",snapshotId,"repositoryName",repository.get("display_name"),"branch",repository.get("tracked_branch")));List<Map<String,Object>> rows=jdbc.queryForList("select sr.id,sr.stage_key from stage_run sr join workflow_run_git_repository_stage rs on rs.workflow_run_git_repository_id=? and rs.stage_key=sr.stage_key where sr.workflow_run_id=? and sr.status='RUNNING'",snapshotId,runId);for(Map<String,Object> row:rows)createWatch(runId,((Number)row.get("id")).longValue(),snapshotId);}
    private void createWatch(Long runId,Long stageRunId,Long snapshotId){Map<String,Object> repository=jdbc.queryForMap("select normalized_url,tracked_branch,display_name from workflow_run_git_repository where id=?",snapshotId);String sha=remote.head(String.valueOf(repository.get("normalized_url")),String.valueOf(repository.get("tracked_branch"))).commitSha();jdbc.update("insert ignore into stage_git_watch(time_created,time_updated,stage_run_id,workflow_run_git_repository_id,baseline_commit_sha,latest_commit_sha,status,last_polled_at,next_poll_at) values(now(3),now(3),?,?,?,?,'WATCHING',now(3),date_add(now(3),interval ? second))",stageRunId,snapshotId,sha,sha,Math.max(1,properties.getPollInterval().toSeconds()));jdbc.update("insert ignore into git_commit_observation(workflow_run_git_repository_id,commit_sha,observation_type,observed_at) values(?,?,'INITIAL',now(3))",snapshotId,sha);publish(runId,stageRunId,"repository.watch.started",Map.of("stageId",stageRunId,"repositoryId",snapshotId,"repositoryName",repository.get("display_name"),"branch",repository.get("tracked_branch"),"commit",sha));}
    @Transactional(readOnly=true) public GitStageStatus status(Long runId,Long stageRunId,Long actor){member(runId,actor);Map<String,Object> stage=jdbc.queryForMap("select sr.stage_key,sr.status from stage_run sr where sr.id=? and sr.workflow_run_id=?",stageRunId,runId);List<WatchView> watchViews=jdbc.query("select w.id,r.id,r.display_name,r.normalized_url,r.tracked_branch,w.baseline_commit_sha,w.latest_commit_sha,w.status,w.last_polled_at,w.next_poll_at,w.consecutive_failures,w.last_error from stage_git_watch w join workflow_run_git_repository r on r.id=w.workflow_run_git_repository_id where w.stage_run_id=? order by w.id",(rs,n)->new WatchView(rs.getLong(1),rs.getLong(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getString(6),rs.getString(7),rs.getString(8),rs.getTimestamp(9)==null?null:rs.getTimestamp(9).toInstant(),rs.getTimestamp(10)==null?null:rs.getTimestamp(10).toInstant(),rs.getInt(11),rs.getString(12),observations(rs.getLong(2))),stageRunId);return new GitStageStatus(stageRunId,String.valueOf(stage.get("stage_key")),String.valueOf(stage.get("status")),watchViews);}
    @Transactional public void refresh(Long runId,Long stageRunId,Long actor){member(runId,actor);for(Long id:jdbc.query("select id from stage_git_watch where stage_run_id=?",(rs,n)->rs.getLong(1),stageRunId))poll(id);}
    @Transactional public void poll(Long watchId){Map<String,Object> row=jdbc.queryForMap("select w.stage_run_id,w.workflow_run_git_repository_id,w.latest_commit_sha,r.workflow_run_id,r.normalized_url,r.tracked_branch,r.display_name from stage_git_watch w join workflow_run_git_repository r on r.id=w.workflow_run_git_repository_id where w.id=?",watchId);Long run=((Number)row.get("workflow_run_id")).longValue(),stage=((Number)row.get("stage_run_id")).longValue(),repository=((Number)row.get("workflow_run_git_repository_id")).longValue();String old=(String)row.get("latest_commit_sha");try{String url=String.valueOf(row.get("normalized_url")),branch=String.valueOf(row.get("tracked_branch"));String next=remote.head(url,branch).commitSha();if(!next.equals(old)){List<GitRemotePort.CommitMetadata> commits=remote.commits(url,branch,old,next);boolean fastForward=commits.stream().anyMatch(c->old!=null&&old.equals(c.parentSha()));String type=fastForward?"NEW_COMMIT":"FORCE_PUSH";for(GitRemotePort.CommitMetadata commit:commits)jdbc.update("insert ignore into git_commit_observation(workflow_run_git_repository_id,commit_sha,parent_sha,author_name,author_email,commit_time,subject,observation_type,observed_at) values(?,?,?,?,?,?,?,?,now(3))",repository,commit.commitSha(),commit.parentSha(),commit.authorName(),commit.authorEmail(),commit.commitTime(),commit.subject(),type);if(commits.isEmpty())jdbc.update("insert ignore into git_commit_observation(workflow_run_git_repository_id,commit_sha,parent_sha,observation_type,observed_at) values(?,?,?,'FORCE_PUSH',now(3))",repository,next,old);jdbc.update("update stage_git_watch set latest_commit_sha=?,status='CHANGED',last_polled_at=now(3),next_poll_at=date_add(now(3),interval ? second),consecutive_failures=0,last_error=null,lease_owner=null,lease_until=null,time_updated=now(3) where id=?",next,Math.max(1,properties.getPollInterval().toSeconds()),watchId);publish(run,stage,fastForward?"repository.commit.detected":"repository.force_push.detected",Map.of("stageId",stage,"repositoryId",repository,"repositoryName",row.get("display_name"),"branch",row.get("tracked_branch"),"previousCommit",old,"commit",next,"subject",commits.isEmpty()?"":commits.get(0).subject()));}else jdbc.update("update stage_git_watch set status='WATCHING',last_polled_at=now(3),next_poll_at=date_add(now(3),interval ? second),consecutive_failures=0,last_error=null,lease_owner=null,lease_until=null,time_updated=now(3) where id=?",Math.max(1,properties.getPollInterval().toSeconds()),watchId);}catch(BusinessException failure){boolean missing="GIT_BRANCH_NOT_FOUND".equals(failure.getCode());jdbc.update("update stage_git_watch set status=?,last_polled_at=now(3),next_poll_at=date_add(now(3),interval least(?,power(2,least(consecutive_failures,10))*? ) second),consecutive_failures=consecutive_failures+1,last_error=?,lease_owner=null,lease_until=null,time_updated=now(3) where id=?",missing?"BRANCH_MISSING":"ERROR",properties.getPollMaxBackoff().toSeconds(),Math.max(1,properties.getPollInterval().toSeconds()),failure.getMessage(),watchId);publish(run,stage,missing?"repository.branch.missing":"repository.poll.failed",Map.of("stageId",stage,"repositoryId",repository,"repositoryName",row.get("display_name"),"branch",row.get("tracked_branch"),"error",failure.getMessage()));}}
    private List<CommitView> observations(Long repository){return jdbc.query("select commit_sha,parent_sha,author_name,author_email,commit_time,subject,observation_type,observed_at from git_commit_observation where workflow_run_git_repository_id=? order by coalesce(commit_time,observed_at) desc,observed_at desc,id desc",(rs,n)->new CommitView(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getTimestamp(5)==null?null:rs.getTimestamp(5).toInstant(),rs.getString(6),rs.getString(7),rs.getTimestamp(8).toInstant()),repository);}
    private void member(Long run,Long actor){Integer n=jdbc.queryForObject("select count(*) from workflow_run w join virtual_project_member m on m.project_id=w.project_id and m.user_id=? and m.status='ACTIVE' where w.id=?",Integer.class,actor,run);if(n==null||n==0)throw new BusinessException("PROJECT_ACCESS_FORBIDDEN","Project membership required",HttpStatus.FORBIDDEN);} private void publish(Long run,Long stage,String type,Map<String,Object> data){var stored=events.append(type+"-"+UUID.randomUUID(),run,stage,null,null,type,data);sse.publish(run,stored);}
    public record GitStageStatus(Long stageRunId,String stageKey,String stageStatus,List<WatchView> watches){} public record WatchView(Long id,Long repositoryId,String repositoryName,String normalizedUrl,String branch,String baselineCommit,String latestCommit,String status,Instant lastPolledAt,Instant nextPollAt,int consecutiveFailures,String lastError,List<CommitView> commits){} public record CommitView(String commitSha,String parentSha,String authorName,String authorEmail,Instant commitTime,String subject,String observationType,Instant observedAt){}
}
